// ❌ OLD: postMessage without transferables STRUCTURE-CLONES the data.
// For a 100MB buffer that means a full copy (allocation + serialize +
// deserialize) on every message — latency and memory spikes.
const worker = new Worker('worker.js');
const bigData = new Float32Array(25_000_000); // 100MB

// ❌ OLD: each postMessage clones this entire array across threads
worker.postMessage(bigData); // main → worker: full copy
worker.onmessage = (e) => {
  const result = e.data; // another full copy back
  console.log(result);
};

// ✅ NEW: Share the buffer once, then coordinate with Atomics.
// No per-message copies — both threads read/write the same bytes.
const worker = new Worker('worker.js');
const sab = new SharedArrayBuffer(100_000_000); // ✅ NEW: shared, no copy
const view = new Float32Array(sab);

worker.postMessage(sab); // transfer the capability once

view[0] = 1; // write before handoff
// ✅ NEW: publish the value, then notify the worker to proceed
Atomics.store(new Int32Array(sab, 0, 1), 0, 1);
Atomics.notify(new Int32Array(sab, 0, 1), 0);

